insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-946')::uuid, md5('building-papenreye-51-65-22453')::uuid, '946', 'kompakte-bueroflaeche-in-top-lage-guenstig-und-ideal-fuer-start-ups-946', 'Kompakte Bürofläche in Top-Lage - günstig und ideal für Start-ups', 'Der Hamburger Workport befindet sich in verkehrsgünstiger Lage zwischen Eppendorf und Fuhlsbüttel, mit einer sehr guten Anbindung an die Autobahn und in unmittelbarer Nähe zum …', 'Der Hamburger Workport befindet sich in verkehrsgünstiger Lage zwischen Eppendorf und Fuhlsbüttel, mit einer sehr guten Anbindung an die Autobahn und in unmittelbarer Nähe zum Hamburger Flughafen. Die aufwendig modernisierten Gebäude verfügen über repräsentative Eingangsbereiche und großzügige Treppenhäuser mit Personen- und Lastenaufzügen. Zur Ausstattung der neu ausgebauten Büroflächen zählt u. a. ein Teppichboden, glatt verputzte Decken und Wände sowie Holzfenster und Beleuchtung. Eine Teeküche, eine großzügige WC-Anlage und der Flurbereich werden gemeinschaftlich genutzt. Die monatliche Miete für diesen Büroraum beträgt pauschal 350,00 Euro inkl. Strom, Wasser, Heizung und Reinigung der Gemeinschaftsflächen und steht ab sofort zur Anmietung zur Verfügung. PKW-Stellplätze können auf dem Gelände bei Bedarf zusätzlich angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'monat', 'inkl. NK, zzgl. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter.', array['lastenaufzug', 'stellplaetze']::text[], 15, 60, 'https://www.buerohamburg.de/objects/pdf/BHI_946.pdf', null, 'filemaker', '946') on conflict (id) do nothing;
insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-946-1')::uuid, md5('property-946')::uuid, 'Mietfläche', 15, 23.33, 350, 'filemaker', '946-1') on conflict (id) do nothing;
