insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-2352')::uuid, md5('building-luebecker-strasse-1-22087')::uuid, '2352', 'modern-flexibel-pauschal-einzelbueroraum-im-alstertower-2352', 'Modern. Flexibel. Pauschal. Einzelbüroraum im Alstertower', 'Der Alstertower befindet sich in markanter Lage nahe der Alsterschwimmhalle und der U-Bahnstation Lübecker Straße. Das Gebäude verfügt über zwei Personenaufzüge und einen …', 'Der Alstertower befindet sich in markanter Lage nahe der Alsterschwimmhalle und der U-Bahnstation Lübecker Straße. Das Gebäude verfügt über zwei Personenaufzüge und einen großzügigen, modernen Eingangsbereich. Die Büroräume werden in einem frisch renovierten Zustand übergeben und sind mit einem hochwertigen Teppichboden, sowie einer im Fensterbrüstungskanal integrierten EDV-Verkabelung ausgestattet. Eine Teeküche, getrennte WC-Anlagen und der Flur werden gemeinschaftlich genutzt. Der angebotene Büroraum befindet sich im 4. Obergeschoss. Das Büro kostet Euro 480,- monatl. inkl. Strom, Wasser, Heizung und Reinigung der Gemeinschaftsflächen zzgl. MwSt.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-2352-1')::uuid, md5('property-2352')::uuid, 'Mietfläche', 15, 32, 480, 'filemaker', '2352-1') on conflict (id) do nothing;
