insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-24648')::uuid, md5('building-ifflandstrasse-4-22087')::uuid, '24648', 'ihr-einzelbuero-zwischen-berliner-tor-und-aussenalster-24648', 'Ihr Einzelbüro zwischen Berliner Tor und Außenalster', 'Das moderne Bürogebäude befindet sich in unmittelbarer Nähe zur Außenalster und bietet dem Mieter eine sehr gute Infrastruktur. Die U-Bahnstation Lübecker Straße ist nur wenige …', 'Das moderne Bürogebäude befindet sich in unmittelbarer Nähe zur Außenalster und bietet dem Mieter eine sehr gute Infrastruktur. Die U-Bahnstation Lübecker Straße ist nur wenige Gehminuten entfernt und die belebte Lange Reihe in St. Georg mit ihren zahlreichen Cafés, Hotels und Restaurants befindet sich ebenfalls in fußläufiger Entfernung. Der Zugang zur Mietfläche erfolgt über ein repräsentativen Eingangsbereich und zwei gläserne Aufzüge. Zur Ausstattung der lichtdurchfluteten Bürofläche zählen u. a. eine Cat-6-Verkabelung im Hohlraumboden, bodentiefe Fenster, moderne Stehleuchten sowie ein außenliegender Sonnenschutz. Die monatliche Pauschalmiete für die hier angegebene Büroeinheit beträgt 800,00 Euro zzgl. MwSt. und beinhaltet bereits die Nebenkosten sowie Strom und Reinigung der Allgemeinflächen wie Flure, WC-Einheiten und die Teeküche. Pkw-Stellplätze können in der hauseigenen Tiefgarage angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'monat', 'inkl. NK, zzgl. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter.', array['stellplaetze']::text[], 25, 40, 'https://www.buerohamburg.de/objects/pdf/BHI_24648.pdf', null, 'filemaker', '24648') on conflict (id) do nothing;
