insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25564')::uuid, md5('building-schottmuellerstrasse-20a-20251')::uuid, '25564', 'ab-2027-kleine-bueroflaeche-in-ruhiger-eppendorfer-hinterhoflage-25564', 'Ab 2027: Kleine Bürofläche in ruhiger Eppendorfer Hinterhoflage', 'In ruhiger Hoflage der Schottmüllerstraße befindet sich dieses ansprechende, halbrund gestaltete Bürogebäude im Herzen von Eppendorf. Das lebendige Umfeld des Stadtteils bietet …', 'In ruhiger Hoflage der Schottmüllerstraße befindet sich dieses ansprechende, halbrund gestaltete Bürogebäude im Herzen von Eppendorf. Das lebendige Umfeld des Stadtteils bietet eine vielfältige Auswahl an gastronomischen Angeboten sowie zahlreiche Einkaufsmöglichkeiten für den täglichen Bedarf.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25564-1')::uuid, md5('property-25564')::uuid, 'Mietfläche', 26, 26.92, 700, 'filemaker', '25564-1') on conflict (id) do nothing;
