  (md5('image-25564-2')::uuid, md5('property-25564')::uuid, 'https://www.buerohamburg.de/objects/images/25564/02_webBig.jpg', 'Ab 2027: Kleine Bürofläche in ruhiger Eppendorfer Hinterhoflage – Bild 2', 1, 'filemaker', '25564-02'),
