insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-25149')::uuid, md5('building-haferweg-36-46-22769')::uuid, '25149', 'modernes-buero-im-businesspark-zur-untermiete-25149', 'Modernes Büro im Businesspark zur Untermiete', 'Das Bürogebäude überzeugt durch seine verkehrsgünstige Lage in unmittelbarer Nähe zur Kieler Straße sowie zum S-Bahnhof Diebsteich. Die Autobahn A7 ist in wenigen Minuten …', 'Das Bürogebäude überzeugt durch seine verkehrsgünstige Lage in unmittelbarer Nähe zur Kieler Straße sowie zum S-Bahnhof Diebsteich. Die Autobahn A7 ist in wenigen Minuten erreichbar und gewährleistet eine optimale Anbindung in alle Richtungen. Zur Untermiete steht im 3. OG ein attraktiver Büroraum mit einer Fläche von ca. 17 qm zur Verfügung. Unter Berücksichtigung der anteiligen Gemeinschaftsflächen wird die Einheit mit insgesamt ca. 27 qm angeboten. Der Zugang erfolgt über ein repräsentatives Foyer mit Personenaufzug. Die moderne Ausstattung umfasst unter anderem Teppichboden, außenliegenden elektrischen Sonnenschutz, CAT-7-Verkabelung sowie eine zeitgemäße Beleuchtung. Ein besonderer Vorteil liegt in der Mitnutzung der Gemeinschaftsflächen: Eine Teeküche, getrennte WC-Einheiten sowie ein Konferenzraum stehen in Abstimmung mit dem Hauptmieter zur Verfügung. Darüber hinaus kann bei Bedarf ein klimatisierter Serverraum genutzt werden. Der Büroraum kann flexibel möbliert oder unmöbliert angemietet werden. Der transparente Pauschalmietpreis beinhaltet sämtliche Neben- und Betriebskosten einschließlich Reinigung und Verbrauchsmaterialien und bietet somit eine hohe Planungssicherheit. Kosten für Internet- und Telefonanschlüsse sind nicht im Mietpreis enthalten. Der zugrunde liegende Hauptmietvertrag basiert auf einer Indexmiete. Etwaige Anpassungen werden im Rahmen der Untermiete entsprechend weitergegeben.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-25149-1')::uuid, md5('property-25149')::uuid, 'Mietfläche', 27, 17.96, 485, 'filemaker', '25149-1') on conflict (id) do nothing;
