insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-2353')::uuid, md5('building-luebecker-strasse-1-22087')::uuid, '2353', 'ab-2027-modern-flexibel-pauschal-einzelbueroraum-im-alstertower-2353', 'Ab 2027: Modern. Flexibel. Pauschal. Einzelbüroraum im Alstertower', 'Der Alstertower befindet sich in markanter Lage an der Kreuzung Lübecker Straße und Sechslingspforte unweit der Außenalster und nur wenige Fahrminuten von der Hamburger Innenstadt …', 'Der Alstertower befindet sich in markanter Lage an der Kreuzung Lübecker Straße und Sechslingspforte unweit der Außenalster und nur wenige Fahrminuten von der Hamburger Innenstadt entfernt. Das Gebäude verfügt über zwei Personenaufzüge und einen großzügigen und modernen Eingangsbereich. Die Büroräume werden in einem frisch renovierten Zustand übergeben und sind mit einem Teppichboden sowie einer im Fensterbrüstungskanal integrierten CAT 5 Verkabelung ausgestattet. Eine Teeküche, getrennte WC-Anlagen und der Flur werden gemeinschaftlich genutzt. Diese Gemeinschaftsflächen werden mit ca. 5 qm anteilig zur Mietfläche addiert. Das vakante Büro im 2. OG kostet pauschal Euro 780,- monatl. inkl. Strom, Wasser, Heizung und Reinigung der Gemeinschaftsflächen zzgl. MwSt.. Im benachbarten Novotel stehen sowohl Konferenzräume als auch Tiefgaragenstellplätze zur Anmietung bereit.insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-2353-1')::uuid, md5('property-2353')::uuid, 'Mietfläche', 30, 26, 780, 'filemaker', '2353-1') on conflict (id) do nothing;
