insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-6139')::uuid, md5('building-papenreye-51-65-22453')::uuid, '6139', 'geraeumiges-buero-nahe-flughafen-und-a7-ideal-und-preiswert-6139', 'Geräumiges Büro nahe Flughafen und A7. Ideal und preiswert.', 'Der Hamburger Workport befindet sich in verkehrsgünstiger Lage zwischen Eppendorf und Fuhlsbüttel, mit einer sehr guten Anbindung an die Autobahn A7 und in unmittelbarer Nähe zum …', 'Der Hamburger Workport befindet sich in verkehrsgünstiger Lage zwischen Eppendorf und Fuhlsbüttel, mit einer sehr guten Anbindung an die Autobahn A7 und in unmittelbarer Nähe zum Hamburger Flughafen. Die aufwendig modernisierten Gebäude verfügen über repräsentative Eingangsbereiche und großzügige Treppenhäuser mit Personen- und Lastenaufzügen. Zur Ausstattung der Büroflächen zählt u. a. ein Teppichboden, glatt verputzte Decken und Wände sowie Holzfenster und Deckenbeleuchtung. Eine Teeküche, eine großzügige WC-Anlage und der Flurbereich werden gemeinschaftlich genutzt. Die monatliche Miete für diese Büroräume beträgt pauschal 530,00 Euro inkl. Strom, Wasser, Heizung und Reinigung der Gemeinschaftsflächen. PKW-Stellplätze können bei Bedarf auf dem Gelände angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'monat', 'inkl. NK, zzgl. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter.', array['lastenaufzug', 'stellplaetze']::text[], 15, 60, 'https://www.buerohamburg.de/objects/pdf/BHI_6139.pdf', null, 'filemaker', '6139') on conflict (id) do nothing;
