  (md5('image-25153-2')::uuid, md5('property-25153')::uuid, 'https://www.buerohamburg.de/objects/images/25153/02_webBig.jpg', 'Modernes Büro im Businesspark zur Untermiete – Bild 2', 1, 'filemaker', '25153-02'),
