insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-16025')::uuid, md5('building-ueberseeboulevard-2-4-20457')::uuid, '16025', 'kleine-kompakte-ladenflaeche-direkt-am-ueberseeboulevard-16025', 'Kleine, kompakte Ladenfläche direkt am Überseeboulevard', 'Die kleine, aber effiziente Ladenfläche befindet sich direkt am Überseeboulevard in der stetig wachsenden HafenCity. Die besonders von Touristen frequentierte Lage und die bereits …', 'Die kleine, aber effiziente Ladenfläche befindet sich direkt am Überseeboulevard in der stetig wachsenden HafenCity. Die besonders von Touristen frequentierte Lage und die bereits begonnene Erschließung des südlichen Überseequartiers machen diesen Standort immer attraktiver. Nach Beendigung des Bauvorhabens entsteht hier neben Wohnraum für ca. 15.000 Menschen und dem neuen Kreuzfahrtterminal auch ein Multiplexkino, 3 weitere Hotels und ein großes Einkaufsquartier mit ca. 80.000 Quadratmetern Einzelhandelsflächen. Auch mittlerweile schon beleben neben guten Einkaufsmöglichkeiten, diversen Restaurants, Cafés und Clubs sowie Boutiquen, Galerien und Wellnessangeboten diese aufstrebende Lage. Die Fläche verfügt über eine WC-Einheit und überzeugt mit einer lichten Raumhöhe und bodentiefen Fenstern mit hervorragender Sichtbarkeit. Die Leichtbauwände werden auf Wunsch zurückgebaut.', 'laden-gastro', array['laden-gastro']::property_category[], 'laden', 'published', 'qm', 'zzgl. NK u. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter bei Abschluss eines Mietvertrages mit einer festen Mietlaufzeit von mindestens 5 Jahren.', array['erdgeschoss']::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_16025.pdf', null, 'filemaker', '16025') on conflict (id) do nothing;
