insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-19879')::uuid, md5('building-gerhofstrasse-2-20354')::uuid, '19879', 'kompakte-bueroflaechen-in-zentraler-innenstadtlage-19879', 'Kompakte Büroflächen in zentraler Innenstadtlage', 'Das historische Kontorgebäude aus dem Jahr 1911 befindet sich in bester Hamburger Innenstadtlage zwischen Gänsemarkt und Großen Bleichen. Die Anbindung an das öffentliche …', 'Das historische Kontorgebäude aus dem Jahr 1911 befindet sich in bester Hamburger Innenstadtlage zwischen Gänsemarkt und Großen Bleichen. Die Anbindung an das öffentliche Verkehrsnetz ist durch die nahe gelegenen U- und S-Bahnstationen Gänsemarkt und Jungfernstieg gesichert. Alle Geschäfte des täglichen Bedarfs sowie zahlreiche Restaurants und Cafés prägen das direkte Umfeld. insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-19879-1')::uuid, md5('property-19879')::uuid, 'Mietfläche', 48, 30, null, 'filemaker', '19879-1') on conflict (id) do nothing;
