insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-109')::uuid, md5('building-papenreye-63-22453')::uuid, '109', 'helle-und-moderne-bueroeinheit-im-hamburger-workport-109', 'Helle und moderne Büroeinheit im Hamburger Workport', 'Der Hamburger Workport befindet sich in verkehrsgünstiger Lage zwischen Eppendorf und Fuhlsbüttel, mit einer sehr guten Anbindung an die Autobahn und in unmittelbarer Nähe zum …', 'Der Hamburger Workport befindet sich in verkehrsgünstiger Lage zwischen Eppendorf und Fuhlsbüttel, mit einer sehr guten Anbindung an die Autobahn und in unmittelbarer Nähe zum Hamburger Flughafen. Die aufwendig modernisierten Gebäude verfügen über repräsentative Eingangsbereiche und großzügige Treppenhäuser mit Personen- und Lastenaufzügen. Zur Ausstattung der neu ausgebauten Büroflächen zählt u. a. ein Teppichboden, glatt verputzte Decken und Wände sowie Holzfenster und Deckenbeleuchtung. Die Fläche ist in zwei Räume mit je ca. 30 qm aufgeteilt, welche mit einer internen Flügeltür verbunden sind. Eine Teeküche, eine großzügige WC-Anlage und der Flurbereich werden gemeinschaftlich genutzt. Die monatliche Miete für diese Büroräume beträgt pauschal 1.060,00 Euro inkl. Strom, Wasser, Heizung und Reinigung der Gemeinschaftsflächen. PKW-Stellplätze können bei Bedarf zusätzlich auf dm Gelände angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'monat', 'inkl. NK, zzgl. MwSt.', true, null, 'Dieses Mietangebot ist courtagefrei für den Mieter.', array['lastenaufzug', 'stellplaetze']::text[], 15, 60, 'https://www.buerohamburg.de/objects/pdf/BHI_109.pdf', null, 'filemaker', '109') on conflict (id) do nothing;
insert into rental_units (id, property_id, label, area_sqm, rent_per_sqm, rent_total_monthly, source, external_id) values (md5('unit-109-1')::uuid, md5('property-109')::uuid, 'Mietfläche', 60, 17.67, 1060, 'filemaker', '109-1') on conflict (id) do nothing;
