insert into properties (id, building_id, reference_number, slug, title, teaser, description, category, categories, property_type, status, price_type, price_note, commission_free, commission_months, commission_note, features, area_range_min_sqm, area_range_max_sqm, expose_pdf_url, featured_rank, source, external_id) values (md5('property-3436')::uuid, md5('building-kampstrasse-7-20357')::uuid, '3436', 'sternschanze-kleines-buero-im-trendigen-umfeld-3436', 'Sternschanze: Kleines Büro im trendigen Umfeld', 'Das moderne Bürogebäude befindet sich zentral im lebendigen Schanzenviertel. Vielseitige Einkaufsmöglichkeiten, zahlreiche Restaurants, Bars und Kneipen prägen diese immer noch …', 'Das moderne Bürogebäude befindet sich zentral im lebendigen Schanzenviertel. Vielseitige Einkaufsmöglichkeiten, zahlreiche Restaurants, Bars und Kneipen prägen diese immer noch trendige Lage in unmittelbarer Nähe zum Schulterblatt und dem Neuen Pferdemarkt. Die in wenigen Gehminuten erreichbare U- und S-Bahnstation Sternschanze sichert einen sehr guten Anschluss an den ÖPNV. Die Ausstattung der hellen Bürofläche umfasst u.a. eine eingerichtete Teeküche sowie eine WC-Einheit. Die weitere Ausstattung und Aufteilung erfolgt in Absprache mit dem zukünftigen Mieter. PKW-Stellplätze können im Umfeld angemietet werden.', 'buero-praxis', array['buero-praxis']::property_category[], 'buero', 'published', 'qm', 'zzgl. NK u. MwSt.', false, 3, 'Dieses Mietangebot ist courtagepflichtig für den Mieter.*', '{}'::text[], null, null, 'https://www.buerohamburg.de/objects/pdf/BHI_3436.pdf', null, 'filemaker', '3436') on conflict (id) do nothing;
